public class Book {
    // class members
    private String title;
    private String author;
    private double price;

    // constructor
    public Book() {
        title = "";
        author = "";
        price = 0.0;
    }

    // overloaded
    public Book(String title, String author, double price) {
        this.title = title;
        this.author = author;
        this.price = price;
    }

    // getter methods, generated by intelliJ
    public String getTitle() {
        return title;
    }

    public String getAuthor() {
        return author;
    }

    public double getPrice() {
        return price;
    }

    // toString, generated by IntelliJ
    @Override
    public String toString() {
        return "Book{" +
                "title='" + title + '\'' +
                ", author='" + author + '\'' +
                ", price=" + price +
                '}';
    }
}
